2510:function Invoke-WorkflowFailTurn {
2511:    # TR-MCP-REPL-020: close the active turn as failed from plugin cache state
2512:    # (BUG-TRIAGE-099). workflow.sessionlog.failTurn cannot be dispatched to the
2513:    # REPL for plugin-shim turns: the in-process SessionLogWorkflow throws
2514:    # 'No active session exists' because the PowerShell shim's beginTurn never
2515:    # creates REPL-native state (that in-process contract is correct for
2516:    # REPL-native sessions and stays untouched). Following the
2517:    # appendDialog/appendActions pattern, the session and turn are resolved from
2518:    # session-state.yaml + current-turn.yaml, the turn is persisted with status
2519:    # 'failed' and the failure note, and current-turn.yaml is cleared so the
2520:    # Stop hook sees a closed turn.
2521:    param([string]$ParamsYaml)
2522:    $turnFile = Get-ReplCurrentTurnFile
2523:    if (-not (Test-Path $turnFile)) {
2524:        return (Deny-ReplMissingCurrentTurn -Method 'workflow.sessionlog.failTurn')
2525:    }
2526:    if (-not (Assert-ReplCurrentTurnFresh -Method 'workflow.sessionlog.failTurn')) {
2527:        return $false
2528:    }
2529:
2530:    # errorMessage is the canonical REPL contract parameter (IFailTurnParams);
2531:    # failureNote is accepted as an alias for symmetry with the persisted field.
2532:    $errorMessage = Get-ReplParamString -ParamsYaml $ParamsYaml -Name 'errorMessage'
2533:    if ([string]::IsNullOrWhiteSpace($errorMessage)) {
2534:        $errorMessage = Get-ReplParamString -ParamsYaml $ParamsYaml -Name 'failureNote'
2535:    }
2536:    if ([string]::IsNullOrWhiteSpace($errorMessage)) {
2537:        [Console]::Error.WriteLine('workflow.sessionlog.failTurn requires a non-empty errorMessage (or failureNote).')
2538:        return $false
2539:    }
2540:    $errorCode = Get-ReplParamString -ParamsYaml $ParamsYaml -Name 'errorCode'
2541:    $failureNote = if ([string]::IsNullOrWhiteSpace($errorCode)) { $errorMessage } else { "$errorMessage (errorCode: $errorCode)" }
2542:
2543:    $reqId = Get-ReplTurnCacheField -Field 'turnRequestId'
2544:    $persisted = $false
2545:    try {
2546:        # TR-MCP-REPL-015: omit the title so failing a turn never retitles it.
2547:        $script:ReplPersistVerbMethod = 'workflow.sessionlog.failTurn'
2548:        $persisted = [bool](Invoke-ReplPersistTurn -RequestId $reqId -Title '' `
2549:            -Status 'failed' -ResponseText $failureNote)
2550:    } catch {
2551:        [Console]::Error.WriteLine("workflow.sessionlog.failTurn failed for '$reqId': $_")
2552:        return $false
2553:    }
2554:    if (-not $persisted) {
2555:        if (Test-ReplSessionVerbQueued) {
2556:            [Console]::Error.WriteLine("workflow.sessionlog.failTurn queued for '$reqId'. Failsafe retained; primary persistence was not claimed.")
2557:            return $true
2558:        }
2559:        return $false
2560:    }
2561:
2562:    Remove-Item -LiteralPath $turnFile -Force -ErrorAction SilentlyContinue
2563:    return $true
2564:}
