2753:function Invoke-ReplMethod {
2754:    [CmdletBinding()]
2755:    param(
2756:        [Parameter(Mandatory)][string]$Method,
2757:        [string]$ParamsYaml = ''
2758:    )
2759:
2760:    # Local plugin-shim verbs: record the boolean outcome on the script-scoped
2761:    # success flag (so the script-entry exit code is truthful) and return without
2762:    # emitting the boolean to stdout. Emitting it leaked "True" lines, and leaving
2763:    # the flag unset made the script-entry exit 1 even on a successful persist.
2764:    switch -Wildcard ($Method) {
2765:        'workflow.sessionlog.beginTurn'       { $script:LastInvokeReplMethodSuccess = [bool](Invoke-WorkflowBeginTurn -ParamsYaml $ParamsYaml); return }
2766:        'workflow.sessionlog.openSession'     { $script:LastInvokeReplMethodSuccess = [bool](Invoke-WorkflowOpenSession -ParamsYaml $ParamsYaml); return }
2767:        'workflow.sessionlog.updateTurn'      { $script:LastInvokeReplMethodSuccess = [bool](Invoke-WorkflowUpdateTurn -ParamsYaml $ParamsYaml); return }
2768:        'workflow.sessionlog.appendActions'   { $script:LastInvokeReplMethodSuccess = [bool](Invoke-WorkflowAppendActions -ParamsYaml $ParamsYaml); return }
2769:        'workflow.sessionlog.appendDialog'    { $script:LastInvokeReplMethodSuccess = [bool](Invoke-WorkflowAppendDialog -ParamsYaml $ParamsYaml); return }
