403:    [CmdletBinding()]
404:    param(
405:        [Parameter(Mandatory)][string]$Agent,
406:        [Parameter(Mandatory)][string]$SessionId,
407:        [Parameter(Mandatory)][string]$RequestId,
408:        [Parameter(Mandatory)][string]$Timestamp,
409:        [Parameter(Mandatory)][AllowEmptyString()][string]$QueryText,
410:        [AllowEmptyString()][string]$Title = '',
411:        [Parameter(Mandatory)][string]$Status,
412:        [string]$ResponseText = '',
413:        [Parameter(Mandatory)][string]$Model,
414:        [int]$TokenCount = 0,
415:        [string]$Interpretation = '',
416:        [string[]]$Tags = @(),
417:        [string[]]$ContextList = @(),
418:        [string[]]$FilesModified = @(),
